#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/drivers/firmware/qemu_fwcfg.h> 
#include <zephyr/device.h>
#include <zephyr/sys/util.h>

#define FOO_FILE "opt/org.zephyrproject/foo"
#define FOO_FILE_SIZE 16
#define FOO_FILE_CONTENT "0123456789abcdef"

#define BAR_FILE "opt/org.zephyrproject/bar"
#define BAR_FILE_SIZE 8
#define BAR_FILE_CONTENT "ABCDEFG"

static const struct device *get_fwcfg_device(void)
{
#if DT_HAS_CHOSEN(zephyr_qemu_fwcfg)
	const struct device *const fwcfg = DEVICE_DT_GET(DT_CHOSEN(zephyr_qemu_fwcfg));

	if (!device_is_ready(fwcfg)) {
		/*
		 * This is not an error. The board might not have fw_cfg enabled.
		 * For example, when CONFIG_QEMU_FW_CFG is not enabled.
		 */
		ztest_test_skip();
		return NULL;
	}

	return fwcfg;
#else
	ztest_test_skip();
	return NULL;
#endif
}

ZTEST(fwcfg, test_fwcfg_device_features)
{
	const struct device *fwcfg = get_fwcfg_device();
	uint32_t features;
	int ret;

	ret = qemu_fwcfg_get_features(fwcfg, &features);
	zassert_ok(ret, "failed to get features");
}

ZTEST(fwcfg, test_fwcfg_find_file)
{
	const struct device *fwcfg = get_fwcfg_device();
	const struct qemu_fwcfg_file *file;

	file = qemu_fwcfg_find_file(fwcfg, "etc/smbios/smbios-anchor");
	zassert_not_null(file, "failed to find SMBIOS anchor file");

	file = qemu_fwcfg_find_file(fwcfg, FOO_FILE);
	zassert_not_null(file, "failed to find foo file");
	zassert_equal(file->size, FOO_FILE_SIZE, "unexpected foo file size");

	file = qemu_fwcfg_find_file(fwcfg, BAR_FILE);
	zassert_not_null(file, "failed to find bar file");
	zassert_equal(file->size, BAR_FILE_SIZE, "unexpected bar file size");

	file = qemu_fwcfg_find_file(fwcfg, "this/file/does/not/exist");
	zassert_is_null(file, "found a file that should not exist");
}

ZTEST(fwcfg, test_fwcfg_read_file)
{
	const struct device *fwcfg = get_fwcfg_device();
	const struct qemu_fwcfg_file *file;
	uint8_t buf[32];
	int ret;

	file = qemu_fwcfg_find_file(fwcfg, FOO_FILE);
	zassert_not_null(file, "failed to find foo file");

	ret = qemu_fwcfg_read_file(fwcfg, file, buf, sizeof(buf));
	zassert_equal(ret, FOO_FILE_SIZE, "failed to read foo file");
	zassert_mem_equal(buf, FOO_FILE_CONTENT, FOO_FILE_SIZE, "unexpected foo file content");

	file = qemu_fwcfg_find_file(fwcfg, BAR_FILE);
	zassert_not_null(file, "failed to find bar file");

	ret = qemu_fwcfg_read_file(fwcfg, file, buf, sizeof(buf));
	zassert_equal(ret, BAR_FILE_SIZE, "failed to read bar file");
	zassert_mem_equal(buf, BAR_FILE_CONTENT, BAR_FILE_SIZE, "unexpected bar file content");
}

ZTEST_SUITE(fwcfg, NULL, NULL, NULL, NULL, NULL);
